        "uri": "huaweischeme://healthapp/home/sport?sportType=2"
      }
    }
  ],
  "dataModel": {
    "value": {
      "fitness": {
        "title": "跑步",
        "warning": "快不行了",
        "actionText": "点按进入运动健康",
        "asset": {
          "runIcon": "resources/base/media/icon_run.png"
        }
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "run_icon",
      "src": "resources/base/media/icon_run.png",
      "use": "running glyph",
      "description": "跑步图标素材，用作运动健身卡片的主体视觉。",
      "bindTo": "/fitness/asset/runIcon",
      "static": true
    }
  ]
}

